import sys, importlib.util as iu
def L(n,p):
    s=iu.spec_from_file_location(n,p); m=iu.module_from_spec(s); sys.modules[n]=m; s.loader.exec_module(m); return m
fc=L('t','/home/hera/measurement_env/hera/models/tetralayer_fs_count/fs_count_b0.py')
for u,lab in ((3.2,'1e12 units'),(3.2e12,'cm^-2'),(3.2e16,'m^-2')):
    try:
        print(lab, '->', fc.abab_fs(u)[1], fc.abca_fs(u)[4])
    except Exception as e:
        print(lab,'ERR',type(e).__name__,str(e)[:120])
"

